"""Sprachdialog, Rückfragen und lokale Antworten."""from __future__ import annotationsimport asyncioimport datetime as dtimport randomimport reimport timeimport uuidfrom typing import TYPE_CHECKINGfrom zoneinfo import ZoneInfofrom ..catalog import normalize as normalize_commandfrom ..intents import parsefrom ..math_de import evaluate, format_numberif TYPE_CHECKING:    from ..core import Coreasync def handle_text(core: Core, text: str, session: str, request_id: str) -> dict:    core.attend()    text = re.sub(r"^(?:hey\s+)?rovo[,\s]*", "", text.strip(), flags=re.I)    parsed = parse(text)    now_power = time.monotonic()    if parsed.name in {"system.shutdown", "system.restart"}:        core.pending.pop(session, None)        core.people.cancel()        core.power_pending[session] = (now_power + 20, parsed.name)        verb = "herunterfahren" if parsed.name == "system.shutdown" else "neu starten"        return core.result(            request_id,            f"Soll ich {verb}? Bitte innerhalb von 20 Sekunden bestätigen.",            intent=parsed.name,            status="confirmation_required",        )    power = core.power_pending.pop(session, None)    if power and parsed.name == "confirmation" and now_power <= power[0]:        if not core.config["simulation"]:            import sys            if (                not core.power_authorized                or core.config["safe_mode"]                or sys.platform != "linux"            ):                raise ValueError(                    "Systemaktion gesperrt: Linux, Safe Mode aus und --allow-power-actions erforderlich."                )        await core.action("stop", {}, session)        if core.config["simulation"]:            return core.result(                request_id,                "Systemaktion simuliert; der Rechner läuft weiter.",                intent=power[1],            )        process = await asyncio.create_subprocess_exec(            "systemctl",            "poweroff" if power[1] == "system.shutdown" else "reboot",            stdout=asyncio.subprocess.DEVNULL,            stderr=asyncio.subprocess.DEVNULL,        )        if await asyncio.wait_for(process.wait(), 5) != 0:            raise ValueError("Systemaktion abgewiesen; lokale Berechtigungen prüfen.")        return core.result(            request_id,            "Systemaktion angefordert.",            intent=power[1],            status="acknowledged",        )    intent, args, now = parsed.name, parsed.args, time.monotonic()    if intent in {"unknown", "math.evaluate"}:        answer = core.activities.answer(session, text)        if answer is not None:            return core.result(                request_id,                answer,                intent="game.answer",                data={                    "emotion": "CURIOUS"                    if session in core.activities.games                    else "HAPPY"                },            )    if intent == "alarm.change_index":        alarms = core.activities.alarms()        if not 1 <= args["index"] <= len(alarms):            raise ValueError("Diese Weckernummer gibt es nicht.")        intent, args = (            "alarm.change",            {"id": alarms[args["index"] - 1]["id"], "action": args["action"]},        )    if intent == "alarm.change_one":        alarms = core.activities.alarms()        if len(alarms) != 1:            return core.result(                request_id,                "Bitte liste die Wecker auf und nenne die Nummer, zum Beispiel: Lösche Wecker zwei.",                intent="clarify",            )        intent, args = "alarm.change", {"id": alarms[0]["id"], "action": args["action"]}    reply, data = "", {}    job = core.people.job    if job and job["state"] == "WAIT_NAME" and job.get("session") in {None, session}:        core.pending.pop(session, None)        if intent == "confirmation":            return core.result(                request_id,                "Bitte nenne zuerst deinen Namen. Eine Einwilligung frage ich danach gesondert ab.",                intent="people.name",            )        if intent == "unknown" and re.fullmatch(            r"[A-Za-zÄÖÜäöüß][A-Za-zÄÖÜäöüß'\-]{0,39}(?: [A-Za-zÄÖÜäöüß][A-Za-zÄÖÜäöüß'\-]{0,39})?",            text.strip().rstrip(".!?"),        ):            if text.lower().split()[0] not in {                "was",                "wie",                "warum",                "wer",                "wann",                "wo",                "kannst",                "erzähl",                "ich",            }:                intent, args = "people.name", {"name": text.strip().rstrip(".!?")}    if intent == "cancel":        core.people.cancel()    if job and job["state"] == "WAIT_CONSENT" and job["session"] == session:        if intent == "confirmation" or normalize_command(text) in {            "ja du darfst mein gesicht speichern",            "ja das darfst du",        }:            data, reply, status = await core.action(                "people.enroll.confirm",                {"token": job["token"], "consent": True},                session,            )            return core.result(                request_id,                reply,                data=data,                intent="people.enroll.confirm",                status=status,            )        if intent in {"negated", "cancel"}:            core.people.cancel()        elif intent != "people.status":            core.people.cancel()  # Ein späteres Ja darf nicht auf einen anderen Dialog passen.    if intent == "people.name":        data, reply, status = await core.action(            "people.enroll.request",            {                "name": args["name"],                "store_images": core.config["people"]["store_images"],            },            session,        )        return core.result(request_id, reply, data=data, intent=intent, status=status)    if intent == "people.enroll":        if core.people.job and core.people.job["state"] != "WAIT_NAME":            raise ValueError(                "Eine Anmeldung läuft bereits. Zuerst ausdrücklich abbrechen."            )        obs = core.people._fresh_target()        core.people.job = {            "state": "WAIT_NAME",            "track_id": obs.track_id,            "deadline": now + 60,            "session": session,        }        return core.result(            request_id,            "Wie heißt du? Sage zum Beispiel: Ich heiße Max. Danach frage ich nach deiner Einwilligung.",            intent=intent,        )    if intent == "people.identify":        person = core.people.current_person()        name = next(p["name"] for p in core.people.profiles() if p["id"] == person)        return core.result(request_id, f"Ich erkenne dich als {name}.", intent=intent)    if intent in {"people.facts", "people.fact.add", "people.topic"}:        person = core.people.current_person()        if intent == "people.fact.add":            ident = core.people.add_fact(person, "Allgemein", args["fact"], False)            return core.result(                request_id,                "Diese Information habe ich mit deinem Auftrag lokal in deinem Profil gespeichert.",                intent=intent,                data={"id": ident},            )        facts = core.people.facts(person)        if intent == "people.topic":            topic = args["topic"].casefold()            facts = [                f for f in facts if topic in (f["topic"] + " " + f["text"]).casefold()            ]        return core.result(            request_id,            "; ".join(f["text"] for f in facts)            or "Dazu habe ich keine Profilinformation gespeichert.",            intent=intent,            data={"facts": facts},        )    # Jede neue Äußerung bindet eine Bestätigung an genau die vorherige Aktion.    if intent not in {"confirmation", "notes.delete_last"}:        core.pending.pop(session, None)    if intent == "motion.repeat":        previous = core.followups.get(session)        if not previous or previous[0] < now:            return core.result(                request_id, "In welche Richtung soll ich schauen?", intent=intent            )        intent, args = previous[1], previous[2]    if intent == "confirmation":        pending = core.pending.get(session)        if not pending or pending[0] < now:            return core.result(                request_id, "Es gibt keine gültige Bestätigungsanfrage.", intent=intent            )        intent, args = (            "notes.delete",            {"id": pending[1], "confirmation_token": pending[2]},        )    if intent == "notes.delete_last":        notes = core.store.notes()        if not notes:            return core.result(                request_id, "Es gibt keine Notiz zum Löschen.", intent=intent            )        token = uuid.uuid4().hex        core.pending[session] = (now + 20, notes[-1]["id"], token)        return core.result(            request_id,            "Soll ich die letzte Notiz löschen? Bitte innerhalb von 20 Sekunden bestätigen.",            intent=intent,            status="confirmation_required",            data={"id": notes[-1]["id"], "confirmation_token": token},        )    if intent == "motion.axis":        if core.motion.pan is None or core.motion.tilt is None:            raise ValueError(                "Noch keine Sollposition bekannt. Zuerst bewusst Home anfordern."            )        intent, args = (            "motion.set",            {                "pan": args["value"] if args["axis"] == "pan" else core.motion.pan,                "tilt": args["value"] if args["axis"] == "tilt" else core.motion.tilt,            },        )    if intent.endswith("_one"):        timers = core.store.timers()        if len(timers) != 1:            return core.result(                request_id,                "Bitte wähle den Timer im Dashboard eindeutig aus.",                intent=intent,            )        args = {            "id": timers[0]["id"],            "action": intent.split(".")[1].removesuffix("_one"),        }        intent = "timer.action"    actions = {        "stop",        "privacy.enable",        "motion.home",        "motion.set",        "motion.relative",        "display.face",        "camera.enable",        "camera.disable",        "tracking.enable",        "tracking.disable",        "notes.add",        "notes.list",        "notes.delete",        "timer.start",        "timer.status",        "timer.action",        "music.pause",        "music.resume",        "music.stop",        "audio.test",        "people.list",        "people.status",        "audio.settings",        "music.spotify",        "music.adjust",        "music.volume",        "motion.profile",        "motion.sequence",        "behavior.gaze",        "game.start",        "game.cancel",        "stopwatch.action",        "alarm.add",        "alarm.list",        "alarm.change",        "alarm.snooze",        "reminder.add",        "reminder.list",        "reminder.change",        "calibration.auto",        "calibration.status",    }    if intent in actions:        data, reply, status = await core.action(intent, args, session)        if intent == "motion.relative":            core.followups[session] = (now + 20, intent, args.copy())        return core.result(request_id, reply, intent=intent, data=data, status=status)    local_now = dt.datetime.now(ZoneInfo(core.config["timezone"]))    if intent == "time.now":        reply = local_now.strftime("Es ist %H:%M Uhr.")    elif intent == "local.answer":        reply = args["reply"]    elif intent == "date.today":        days = (            "Montag",            "Dienstag",            "Mittwoch",            "Donnerstag",            "Freitag",            "Samstag",            "Sonntag",        )        reply = f"Heute ist {days[local_now.weekday()]}, der {local_now:%d.%m.%Y}."    elif intent == "date.week":        reply = f"Wir haben Kalenderwoche {local_now.isocalendar().week}."    elif intent == "math.evaluate":        value = evaluate(args["expression"])        reply, data = f"Das Ergebnis ist {format_number(value)}.", {"value": value}    elif intent == "units.convert":        from ..units_de import convert        value, label = convert(args["value"], args["source"], args["target"])        data = {"value": value, "unit": args["target"]}        reply = f"Das sind {format_number(value)} {label}."    elif intent == "weather.current":        data = await core.weather.current()        reply = (            f"Am Standort {data['location']} ist es {data['description']} bei "            f"{format_number(data['temperature_c'])} Grad Celsius."        )    elif intent == "about":        reply = "Ich bin Rovo: Robotic Observation and Voice Operator, ein stationärer Tischroboter."    elif intent == "persona":        reply = "Meine Mimik ist Animation. Ich habe keine menschlichen Gefühle."    elif intent == "greeting":        reply = "Hallo, ich bin Rovo."    elif intent == "thanks":        reply = "Gern geschehen."    elif intent == "battery.status":        data = core.power.snapshot()        reply = (            f"Der gemessene Akkustand beträgt {data['battery_percent']:g} Prozent."            if data["battery_percent"] is not None            else "Den Akkustand kann ich gerade nicht auslesen."        )    elif intent == "system.status":        reply, data = "Hier ist der aktuelle Systemstatus.", core.status()    elif intent == "stationary":        reply = "Ich bin ein stationärer Tischroboter und habe keinen Fahrantrieb."    elif intent == "fun.joke":        reply = "Warum können Roboter schlecht lügen? Weil man sie sofort durchschaut, wenn die Verkleidung fehlt."    elif intent == "fun.dice":        reply = f"Du hast eine {random.randint(1, 6)} gewürfelt."    elif intent == "fun.coin":        reply = random.choice(("Kopf.", "Zahl."))    elif intent == "cancel":        core.pending.pop(session, None)        core.followups.pop(session, None)        core.activities.games.pop(session, None)        reply = "Abgebrochen."    elif intent == "negated":        reply = "Ich führe den verneinten Befehl nicht aus."    elif intent == "clarify":        reply = args["reply"]    elif intent == "faces.unavailable":        reply = "Personenidentifikation benötigt eingerichtete lokale Modelle. Frage: Kennst du mich? Für neue Profile: Speichere mein Gesicht."    elif intent == "unsupported_action":        reply = (            "Dieser Gerätebefehl ist nicht freigegeben oder noch nicht eingerichtet."        )    elif intent == "camera.status":        data = core.camera.status()        reply = (            f"Ich erkenne aktuell {data['face_count']} Gesichter."            if data["face_count"] is not None            else "Ein aktuelles Kamerabild ist nicht verfügbar."        )    elif intent == "capabilities":        data = core.capabilities()        reply = (            "Verfügbar sind: "            + ", ".join(k for k, v in data.items() if v["available"])            + "."        )    elif intent == "llm.status":        reply = (            f"Eingerichtet ist {core.config['llm']['model']}."            if core.llm.available()            else "Kein KI-Modell eingerichtet."        )    elif intent == "llm.disable":        core.config["llm"]["enabled"] = False        reply = "Text-KI für diese Sitzung deaktiviert."    elif intent == "audio.stop":        await core.audio.stop()        reply = "Sprachausgabe gestoppt."    elif intent == "speech.repeat":        reply = (            core.audio.last_reply or "Es gibt noch keine Sprachausgabe zum Wiederholen."        )    else:        # Feste Wissensantworten kommen bereits als local.answer aus catalog.json.        if core.llm.available() and not core.privacy and core.people.job is None:            epoch = core.cancel_epoch            core.expressions.set("thinking", "THINKING", 50, 25)            try:                answer = await core.llm.respond(                    text,                    {                        "capabilities": core.capabilities(),                        "simulation": core.esp.simulated,                        "safe_mode": core.config["safe_mode"],                        "tracking": core.motion.tracking,                        "camera_online": core.camera.online,                        "power": core.power.snapshot(),                    },                )            finally:                core.expressions.clear("thinking")            reply, data = answer["reply"], {"emotion": answer["emotion"]}            if (                epoch != core.cancel_epoch                or core.privacy                or core.people.job is not None            ):                return core.result(                    request_id,                    "Antwort durch Stopp, Privatsphäre oder Gesichtsanmeldung verworfen.",                    ok=False,                    intent="llm.text",                    status="cancelled",                    code="CANCELLED",                )            intent = "llm.text"        else:            reply = (                "Während der Gesichtsanmeldung bleibt das Textmodell aus. Du kannst den Fortschritt erfragen oder abbrechen."                if core.people.job                else "Dazu habe ich keine lokale Antwort. Ein Textmodell ist nicht verfügbar."            )    return core.result(request_id, reply, intent=intent, data=data)